package com.costeo3d.infrastructure.persistence.dao;

import java.util.List;
import java.util.Optional;

import com.costeo3d.domain.model.Model3D;

/** Persistence contract for the 3D model catalogue. */
public interface Model3DDao {

    // Returns a new instance with the ID generated by MySQL.
    Model3D insert(Model3D model);

    Optional<Model3D> findById(int id);

    // Includes active and inactive models.
    List<Model3D> findAll();

    // Returns false if no model exists with the given ID.
    boolean update(Model3D model);
}
